# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs, factor=3):
    return [v * factor for v in xs]

# region: shape
def shape(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs, offset=1):
    return [v + offset for v in xs[1:]]

# region: intake
def intake(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: fold
def fold(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return fold(intake(sift(shape(emit(render(raw))))))

